from common import *
src('igeeks-v3'); dom('expressjs')
topic('Routing')
M('b','k',"Which method creates an Express application?","express()","new Express()","express.create()","createApp()","const app = express() returns the application object.")
M('b','k',"Which method starts an Express app listening for connections?","app.listen(port)","app.start(port)","app.run(port)","app.open(port)","app.listen binds to a port and returns an http.Server.")
M('b','k',"Which method defines a handler for GET requests to /users?","app.get('/users', handler)","app.route.get('/users')","app.fetch('/users')","app.on('GET /users')","Express has one method per HTTP verb, such as get, post, put and delete.")
M('b','k',"How do you read a route parameter from /users/:id?","req.params.id","req.query.id","req.body.id","req.id","Parameters named in the path are placed in req.params.")
M('b','k',"How do you read ?page=2 from the URL?","req.query.page","req.params.page","req.body.page","req.url.page","The query string is parsed into req.query. Values are strings.")
topic('Request & Response')
M('b','k',"Which method sends a JSON response?","res.json(data)","res.sendJSON(data)","res.write.json(data)","res.body(data)","res.json stringifies the value and sets the Content-Type header.")
M('b','k',"How do you set the HTTP status code of a response?","res.status(404)","res.code = 404","res.statusCode(404)","res.set(404)","res.status(404).json({ error: 'Not found' }) sets the code and sends a body.")
M('b','k',"Which built-in middleware serves static files such as images and CSS?","express.static('public')","express.files('public')","express.serve('public')","app.static('public')","express.static maps a folder to URL paths.")
M('b','k',"Which middleware parses a JSON request body?","express.json()","express.parse()","express.body()","app.json()","After app.use(express.json()) the parsed data is in req.body.")
topic('Middleware')
M('b','k',"What is middleware in Express?","A function that receives req, res and next and can handle or pass on the request","A database driver","A template engine","A kind of route","Middleware runs in the order it is registered and may end the response or call next().")
M('b','k',"What does calling next() inside middleware do?","Passes control to the next middleware or route","Ends the response","Restarts the request","Closes the connection","If a middleware neither responds nor calls next(), the request hangs.")
M('b','k',"Which method registers middleware for every request?","app.use(fn)","app.all(fn)","app.middleware(fn)","app.add(fn)","app.use runs the function for all paths (or paths starting with a given prefix).")
topic('Request & Response')
M('b','k',"Which HTTP status code means a resource was not found?","404","200","500","301","404 Not Found. 200 is OK, 500 is a server error and 301 a permanent redirect.")
M('b','k',"What does res.redirect('/login') do?","Sends a redirect response so the browser requests /login","Includes the login page's HTML","Forwards the request internally","Closes the server","The default status is 302 (Found).")
M('b','k',"What is the usual way to export an Express router from a file?","module.exports = router","export router to app","router.export()","app.export(router)","In CommonJS the file assigns the router to module.exports, and the app mounts it with app.use('/path', router).")
topic('Routing')
M('i','k',"How do you mount a group of routes under /api/users?","app.use('/api/users', usersRouter)","app.route('/api/users', usersRouter)","usersRouter.mount('/api/users')","app.group('/api/users', usersRouter)","A Router is a mini-app. Paths inside it are relative to the mount point.")
M('i','k',"Two routes match: app.get('/users/:id') is declared before app.get('/users/new'). A request for /users/new goes where?","To the :id route, with id = 'new'","To the /users/new route","To a 404","To the last route","Express uses the first matching route, so declare more specific routes before parameterised ones.")
M('i','k',"What does app.route('/books').get(a).post(b) do?","Defines handlers for several methods on one path","Creates two separate servers","Defines two middleware","Redirects GET to POST","Chaining under one path avoids repeating the path string.")
topic('Middleware')
M('i','k',"A middleware has the signature (req, res, next) but never calls next() or sends a response. What happens?","The request hangs until the client times out","Express calls next automatically","A 404 is sent","A 500 is sent","Express does not time out for you. Always finish the response or call next.")
M('i','k',"Where should error-handling middleware be registered?","After all routes and other middleware","Before everything","Inside each route","Only in the router","Error handlers are matched in order, so they must come after the code that might raise errors.")
M('i','k',"What is the signature of Express error-handling middleware?","(err, req, res, next)","(req, res, next, err)","(req, res, err)","(err, res)","Express recognises error handlers by their four parameters, even if next is unused.")
M('i','k',"A route handler is async and throws. In Express 4, what happens if the error is not caught?","The request hangs and an unhandled rejection is raised","Express passes it to the error handler","The process restarts","A 500 is sent automatically","Express 4 does not handle rejected promises, so wrap the handler or call next(err). Express 5 forwards rejections to the error handler.")
topic('Security')
M('i','k',"What does the cors middleware control?","Which other origins may call your API from a browser","Password hashing","Compression","Cookies lifetime","CORS headers tell browsers whether a page on another origin may read the response.")
M('i','k',"Which package adds a set of security-related HTTP headers?","helmet","morgan","multer","passport","helmet sets headers such as X-Content-Type-Options and Content-Security-Policy.")
topic('Request & Response')
M('i','k',"Which middleware is typically used to handle multipart file uploads?","multer","body-parser","cookie-parser","compression","express.json does not parse multipart forms. multer does.")
M('i','k',"What is the difference between res.send and res.json?","res.json always converts to JSON and sets the JSON content type","res.send cannot send strings","res.json is faster","There is no difference","res.send chooses the type from its argument. res.json always stringifies.")
M('i','k',"Why does an Express app not see a JSON body when express.json() is missing?","req.body stays undefined because nothing parses the stream","JSON is blocked by default","The body is in req.query","The request is rejected with 400","Body parsing is optional middleware in Express.")
topic('Middleware')
M('a','k',"You register app.use(express.json()) after the route that reads req.body. What happens?","req.body is undefined in that route","It works the same","The server fails to start","The body is parsed twice","Middleware runs in registration order, so the parser must come before the routes that need it.")
topic('Security')
M('a','k',"Why is it unsafe to build a file path directly from req.params.name, for example fs.readFile('uploads/' + name)?","A value like ../../etc/passwd can escape the folder (path traversal)","fs is asynchronous","Parameters are always numbers","Express blocks dots","Validate or normalise the name and check the resolved path stays inside the intended directory.")
M('a','k',"Which cookie attributes help protect a session cookie?","HttpOnly, Secure and SameSite","Path and Domain only","Max-Age only","Expires only","HttpOnly hides it from JavaScript, Secure sends it only over HTTPS and SameSite limits cross-site sending.")
M('a','k',"Why use rate limiting on a login route?","To slow down brute-force password guessing","To make the page load faster","To hide the route","To reduce cookie size","express-rate-limit or a gateway limits attempts per client in a time window.")
M('a','k',"What does app.set('trust proxy', true) affect?","How Express reads the client IP and protocol behind a reverse proxy via X-Forwarded-* headers","The SSL certificate","The routing order","Static file caching","Without it, req.ip would be the proxy's address and secure cookies may not be set correctly. Only trust proxies you control.")
topic('Request & Response')
M('a','k',"What is wrong with calling res.send twice in the same request?","Headers are already sent, so the second call throws ERR_HTTP_HEADERS_SENT","The second response replaces the first","Nothing, both are sent","The server closes the port","A response can be sent only once. Use return after sending in early-exit branches.")
M('a','k',"What does req.params look like for the route /files/*splat (Express 5) when the URL is /files/a/b.txt?","An array of path segments under the splat name","A single string only","Undefined","The query object","In Express 5 wildcards must be named and are captured as arrays of segments. In Express 4 they were available as req.params[0].")
topic('Middleware')
M('a','k',"Why must an error-handling middleware declare all four parameters even if next is not used?","Express decides it is an error handler from its function length","JavaScript requires every parameter","next is called internally","To keep the stack trace","fn.length is 4 only if all four are declared, which is how Express recognises it.")
M('a','k',"What is a sensible way to avoid repeating try/catch in every async route in Express 4?","A small wrapper that forwards rejected promises to next(err)","Disabling errors","Using sync fs only","Calling res.end first","const wrap = fn => (req, res, next) => fn(req, res, next).catch(next) sends failures to the central handler.")
topic('Security')
M('a','k',"A browser sends an OPTIONS preflight before a cross-origin PUT with a JSON body. What must the server do for the real request to be allowed?","Answer the OPTIONS request with a success status and the matching Access-Control-Allow-* headers","Return 404 for OPTIONS","Add a Content-Length header","Switch the route to GET","The cors middleware must be registered before the routes so that the preflight is answered. Routes that only define PUT never see the OPTIONS request.")
topic('Middleware')
M('a','k',"How does app.use('/api', fn) differ from app.all('/api', fn)?","use matches any path starting with /api and strips the mount path from req.url, while all matches only the exact path","They are identical","all matches any prefix and use matches the exact path","use only handles GET","app.use mounts middleware on a path prefix, so inside fn, req.url is relative to /api. app.all is a route that matches every HTTP method for that exact path.")
